        "testata": "Il Manifesto",
        "lingua_originale": "it",
        "titolo_orig": "Dieci anni dopo, l’ultimo soldato Usa lascia la Siria del nord-est",
        "testo_it": "Gli Stati Uniti completano il ritiro definitivo delle proprie truppe dalle basi nel nord-est della Siria.",
        "priorita": "Alta",
        "id_gruppo": 25,
        "link": "https://ilmanifesto.it/dieci-anni-dopo-lultimo-soldato-usa-lascia-la-siria-del-nord-est",
        "orario": "11:49",
